const raceNames=new Set(CANON.people.map(x=>x.name));const godNames=new Set(CANON.gods.map(x=>x.name));
function raceName(value){const name=String(value||'').split(' • ')[0].split(' :: ')[0].trim();return raceNames.has(name)?name:"Aza’raan";}
function godName(value){return godNames.has(value)?value:'Nefarokir';}
