const calendar={...CANON.calendar,
 getDate(dayOfYear,year=1){const day=((Math.trunc(dayOfYear)%240)+240)%240;return {year,yearDay:day+1,monthIndex:Math.floor(day/30),month:CANON.calendar.months[Math.floor(day/30)],dayInMonth:day%30+1,weekday:CANON.calendar.weekdays[day%6],weekInMonth:Math.floor((day%30)/6)+1,weekInYear:Math.floor(day/6)+1};},
 format(dayOfYear,year=1){const d=this.getDate(dayOfYear,year);return `${d.weekday}, ${d.month} ${d.dayInMonth}, Year ${d.year} · week ${d.weekInMonth}/5`;},
 formatHour(hour){const h=((Math.trunc(hour)%21)+21)%21;const phase=CANON.calendar.moonPeriods[Math.floor(h/7)];return `${phase.name} ${h%7+1}/7`;},
 fromEarth(date=new Date()){const start=Date.UTC(date.getUTCFullYear(),0,1),next=Date.UTC(date.getUTCFullYear()+1,0,1);const day=Math.min(239,Math.floor((date.getTime()-start)/(next-start)*240));return this.getDate(day,date.getUTCFullYear());}
};
